// ── Utilidades ──
function $(id){return document.getElementById(id);}
function validarEmail(e){return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e.trim());}
const v=id=>document.getElementById(id)?.value||'';
const fmt=d=>{if(!d||d==='')return'—';const s=String(d).trim();if(/^\d{4}-\d{2}-\d{2}$/.test(s))return new Date(s+'T12:00:00').toLocaleDateString('es-PE');const dt=new Date(s);return isNaN(dt)?s:dt.toLocaleDateString('es-PE');};
function clearF(ids){ids.forEach(id=>{const el=document.getElementById(id);if(el)el.value=''});}
function escH(str){if(!str)return'';return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}

// ── Toast ──
let TT;
function toast(msg,dur=3200){const t=$('vq-toast');if(!t)return;t.innerHTML=`<svg width="15" height="15" fill="none" stroke="#F0A500" stroke-width="2.5" viewBox="0 0 24 24"><path d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"/></svg> ${msg}`;t.classList.add('show');clearTimeout(TT);TT=setTimeout(()=>t.classList.remove('show'),dur);}

function setSyncStatus(type,label){const b=$('sync-badge');if(!b)return;b.style.display=label?'block':'none';b.textContent=label;b.style.background=type==='ok'?'rgba(34,169,106,.8)':type==='syncing'?'rgba(46,125,214,.8)':'rgba(229,62,62,.8)';}

// ── API ──
async function apiGet(tabla){if(!SESSION?.rancho_id)return[];const res=await fetch(`${SB_URL}/rest/v1/${tabla}?select=*&order=created_at.desc&rancho_id=eq.${SESSION.rancho_id}`,{headers:SB_HEADERS});if(!res.ok){console.error('apiGet',tabla,await res.text());return[];}const rows=await res.json();if(!Array.isArray(rows))return[];return rows.map(r=>normalizarFila(tabla,r));}

async function apiPost(action,tabla,data,id){
  if(action==='insert'){let row=denormalizarFila(tabla,data);if(SESSION?.rancho_id)row.rancho_id=SESSION.rancho_id;const res=await fetch(`${SB_URL}/rest/v1/${tabla}`,{method:'POST',headers:SB_HEADERS,body:JSON.stringify(row)});if(!res.ok)throw new Error(await res.text());return{success:true};}
  if(action==='update'){const payload=denormalizarFila(tabla,data);const clean=Object.fromEntries(Object.entries(payload).filter(([k])=>!['id','rancho_id','created_at'].includes(k)));const res=await fetch(`${SB_URL}/rest/v1/${tabla}?id=eq.${encodeURIComponent(id)}`,{method:'PATCH',headers:SB_HEADERS,body:JSON.stringify(clean)});if(!res.ok)throw new Error(await res.text());return{success:true};}
  if(action==='delete'){const res=await fetch(`${SB_URL}/rest/v1/${tabla}?id=eq.${encodeURIComponent(id)}`,{method:'DELETE',headers:SB_HEADERS});if(!res.ok)throw new Error(await res.text());return{success:true};}
}
function apiPostFast(action,tabla,data,id){if(!isOnline){const q=JSON.parse(localStorage.getItem('vqa_offline_q')||'[]');q.push({action,tabla,data,id,ts:Date.now()});localStorage.setItem('vqa_offline_q',JSON.stringify(q));setSyncStatus('err','📵 Sin conexión');return Promise.resolve({success:true,offline:true});}apiPost(action,tabla,data,id).then(()=>setSyncStatus('ok','☁ Sincronizado')).catch(err=>{console.error('[SB]',tabla,err.message);setSyncStatus('err','⚠ Pendiente sync');});return Promise.resolve({success:true});}

// ── Normalizar ──
function normalizarFila(tabla,r){
  if(tabla==='animales')return{'ID':r.id||'','Arete':r.arete||'','Nombre':r.nombre||'','Raza':r.raza||'','Sexo':r.sexo||'','Nacimiento':r.nacimiento||'','Peso':r.peso||'','Peso(kg)':r.peso||'','Estado':r.estado||'Activo','Madre':r.madre||'','Padre':r.padre||'','Observaciones':r.observaciones||'','Foto':r.foto||'','rancho_id':r.rancho_id};
  if(tabla==='salud')return{'ID':r.id||'','Animal':r.animal||'','Tipo':r.tipo||'','Descripcion':r.descripcion||'','Dosis':r.dosis||'','FechaAplicacion':r.fecha_aplicacion||'','ProximaDosis':r.proxima_dosis||'','Veterinario':r.veterinario||'','Costo':r.costo||'','Observaciones':r.observaciones||''};
  if(tabla==='insem')return{'ID':r.id||'','Hembra':r.hembra||'','Fecha':r.fecha||'','ToroSemen':r.toro_semen||'','Tecnica':r.tecnica||'','Tecnico':r.tecnico||'','PartoEstimado':r.parto_estimado||'','Resultado':r.resultado||'Pendiente','Costo':r.costo||'','Observaciones':r.observaciones||''};
  if(tabla==='partos')return{'ID':r.id||'','Fecha':r.fecha||'','Madre':r.madre||'','ArieteCria':r.arete_cria||'','SexoCria':r.sexo_cria||'','PesoNacimiento':r.peso_nacimiento||'','TipoParto':r.tipo_parto||'','EstadoCria':r.estado_cria||'','Padre':r.padre||'','Observaciones':r.observaciones||''};
  if(tabla==='gastos')return{'ID':r.id||'','Tipo':r.tipo||'','Descripcion':r.descripcion||'','Monto':r.monto||0,'EsIngreso':r.es_ingreso||false,'Fecha':r.fecha||'','Animal':r.animal||'','Observaciones':r.observaciones||''};
  if(tabla==='semen_toros')return{'ID':r.id||'','Nombre':r.nombre||'','Raza':r.raza||'','Codigo':r.codigo||'','Pais':r.pais||'','Pajillas':r.pajillas||0,'Precio':r.precio||0};
  if(tabla==='inventario')return{'ID':r.id||'','Nombre':r.nombre||'','Categoria':r.categoria||'','Unidad':r.unidad||'','Stock':r.stock||0,'Minimo':r.minimo||0,'Precio':r.precio||0,'Proveedor':r.proveedor||'','Vencimiento':r.vencimiento||''};
  return r;
}
function denormalizarFila(tabla,d){
  if(tabla==='animales')return{arete:d['Arete']||d.arete||'',nombre:d['Nombre']||d.nombre||'',raza:d['Raza']||d.raza||'',sexo:d['Sexo']||d.sexo||'',nacimiento:d['Nacimiento']||d.nacimiento||null,peso:d['Peso']||d.peso||null,estado:d['Estado']||d.estado||'Activo',madre:d['Madre']||d.madre||'',padre:d['Padre']||d.padre||'',observaciones:d['Observaciones']||d.observaciones||'',foto:d['Foto']||d.foto||''};
  if(tabla==='salud')return{animal:d['Animal']||'',tipo:d['Tipo']||'',descripcion:d['Descripcion']||'',dosis:d['Dosis']||'',fecha_aplicacion:d['FechaAplicacion']||null,proxima_dosis:d['ProximaDosis']||null,veterinario:d['Veterinario']||'',costo:d['Costo']||null,observaciones:d['Observaciones']||''};
  if(tabla==='insem')return{hembra:d['Hembra']||'',fecha:d['Fecha']||null,toro_semen:d['ToroSemen']||'',tecnica:d['Tecnica']||'',tecnico:d['Tecnico']||'',parto_estimado:d['PartoEstimado']||null,resultado:d['Resultado']||'Pendiente',costo:d['Costo']||null,observaciones:d['Observaciones']||''};
  if(tabla==='partos')return{fecha:d['Fecha']||null,madre:d['Madre']||'',arete_cria:d['ArieteCria']||'',sexo_cria:d['SexoCria']||'',peso_nacimiento:d['PesoNacimiento']||null,tipo_parto:d['TipoParto']||'Natural',estado_cria:d['EstadoCria']||'',padre:d['Padre']||'',observaciones:d['Observaciones']||''};
  if(tabla==='gastos'){const esIng=d['EsIngreso']===true||d['EsIngreso']==='true'||d['EsIngreso']==='SI';return{tipo:d['Tipo']||'',descripcion:d['Descripcion']||'',monto:parseFloat(d['Monto']||0),es_ingreso:esIng,fecha:d['Fecha']||null,animal:d['Animal']||'',observaciones:d['Observaciones']||''};}
  if(tabla==='semen_toros')return{nombre:d['Nombre']||'',raza:d['Raza']||'',codigo:d['Codigo']||'',pais:d['Pais']||'',pajillas:parseInt(d['Pajillas'])||0,precio:parseFloat(d['Precio'])||0};
  return d;
}

