async function recargarTodo(){if(!SESSION?.rancho_id)return;setSyncStatus('syncing','🔄 Sincronizando...');const spin=$('reload-spin');if(spin)spin.style.display='inline-block';try{const safeGet=async t=>{try{return await apiGet(t);}catch(e){console.warn(t,e.message);return[];}};const[a,s,i,p,g,sem,inv]=await Promise.all([safeGet('animales'),safeGet('salud'),safeGet('insem'),safeGet('partos'),safeGet('gastos'),safeGet('semen_toros'),safeGet('inventario')]);DB.animales=a;DB.salud=s;DB.insem=i;DB.partos=p;DB.gastos=g||[];DB.semen_toros=sem||[];DB.inventario=inv||[];DB.animales.forEach(a=>{if(!a['Foto']){const f=localStorage.getItem('vqa_foto_'+a['ID']);if(f)a['Foto']=f;}});renderDash();renderAnimales();renderSalud();renderInsem();renderPartos();renderAlertas();actualizarBadge();setSyncStatus('ok','☁ Conectado');toast('✅ Datos sincronizados');}catch(e){console.error('Error:',e);setSyncStatus('err','❌ Error');toast('❌ Error: '+e.message.substring(0,50));}if(spin)spin.style.display='none';}

