async function iniciarSesion(){
  const email=($('email-login')?.value||'').trim(),pass=$('pass-login')?.value||'';
  $('al-login')?.classList.remove('vis');
  let ok=true;if(!validarEmail(email)){setErr('email-login',true);ok=false;}if(!pass){setErr('pass-login',true);ok=false;}if(!ok)return;
  const btn=$('btn-ingresar');if(btn){btn.textContent='Cargando...';btn.disabled=true;}
  try{
    const res=await fetch(`${SB_URL}/auth/v1/token?grant_type=password`,{method:'POST',headers:{'apikey':SB_KEY,'Content-Type':'application/json'},body:JSON.stringify({email,password:pass})});
    const data=await res.json();
    if(!res.ok||data.error)throw new Error(data.error_description||data.error||'Credenciales incorrectas');
    const ranchoRes=await fetch(`${SB_URL}/rest/v1/ranchos?select=*&limit=1`,{headers:{...SB_HEADERS,'Authorization':'Bearer '+data.access_token}});
    let rancho=null;if(ranchoRes.ok){const rs=await ranchoRes.json();rancho=rs[0]||null;}
    const sesion={user_id:data.user?.id,email:data.user?.email,access_token:data.access_token,nombre:rancho?.nombre_responsable||data.user?.email?.split('@')[0]||'Usuario',rancho:rancho?.nombre||'Mi Ganadería',rancho_id:rancho?.id||data.user?.id};
    localStorage.setItem('vq_sesion',JSON.stringify(sesion));
    mostrarDashboard(sesion);
  }catch(e){const alMsg=$('al-login-msg');if(alMsg)alMsg.textContent=e.message;$('al-login')?.classList.add('vis');}
  finally{if(btn){btn.textContent='Ingresar';btn.disabled=false;}}
}

async function crearCuenta(){
  const nombre=($('reg-nombre')?.value||'').trim(),rancho=($('reg-rancho')?.value||'').trim(),email=($('reg-email')?.value||'').trim(),pass=$('reg-pass')?.value||'';
  $('al-reg')?.classList.remove('vis');
  let ok=true;if(!nombre){setErr('reg-nombre',true);ok=false;}if(!rancho){setErr('reg-rancho',true);ok=false;}if(!validarEmail(email)){setErr('reg-email',true);ok=false;}if(pass.length<8){setErr('reg-pass',true);ok=false;}if(!ok)return;
  const btn=$('btn-registro');if(btn){btn.textContent='Creando...';btn.disabled=true;}
  try{
    const res=await fetch(`${SB_URL}/auth/v1/signup`,{method:'POST',headers:{'apikey':SB_KEY,'Content-Type':'application/json'},body:JSON.stringify({email,password:pass,data:{nombre,rancho}})});
    const data=await res.json();if(!res.ok||data.error)throw new Error(data.error_description||data.error||'Error al crear cuenta');
    toast('✅ Cuenta creada. Revisa tu correo para confirmar.');cambiarTab('login');
  }catch(e){const alMsg=$('al-reg-msg');if(alMsg)alMsg.textContent=e.message;$('al-reg')?.classList.add('vis');}
  finally{if(btn){btn.textContent='Crear cuenta';btn.disabled=false;}}
}

async function recuperar(e){if(e)e.preventDefault();const email=($('email-login')?.value||'').trim();if(!validarEmail(email)){setErr('email-login',true);return;}try{await fetch(`${SB_URL}/auth/v1/recover`,{method:'POST',headers:{'apikey':SB_KEY,'Content-Type':'application/json'},body:JSON.stringify({email})});toast('📧 Enlace enviado a '+email);}catch(e){toast('Error al enviar enlace');}}

function mostrarDashboard(sesion){SESSION=sesion;$('pantalla-login').style.display='none';$('pantalla-dash').style.display='flex';document.body.style.overflow='hidden';const nombre=sesion.nombre||sesion.email||'Usuario';const rancho=sesion.rancho||'Mi Rancho';if($('d-nombre'))$('d-nombre').textContent=nombre;if($('d-rancho'))$('d-rancho').textContent=rancho;recargarTodo();}

function cerrarSesion(){try{localStorage.removeItem('vq_sesion');}catch(e){}SESSION=null;DB={animales:[],salud:[],insem:[],partos:[],gastos:[],semen_toros:[],inventario:[],proveedores:[]};$('pantalla-dash').style.display='none';$('pantalla-login').style.display='flex';document.body.style.overflow='';cerrarSeccion();cambiarTab('login');}

// ══ DASHBOARD ══
function renderDash(){
  const total=DB.animales.filter(a=>a['Estado']!=='Vendido'&&a['Estado']!=='Muerto').length;
  document.querySelectorAll('.stat').forEach((el,i)=>{const num=el.querySelector('.stat-num');if(!num)return;if(i===0)num.textContent=total;else if(i===1)num.textContent=DB.animales.filter(a=>a['Estado']==='Activo').length;else if(i===2)num.textContent=DB.animales.filter(a=>a['Estado']==='Gestante').length;else if(i===3)num.textContent=DB.animales.filter(a=>a['Estado']==='En tratamiento').length;else if(i===4)num.textContent=DB.animales.filter(a=>a['Estado']==='Muerto').length;});
  actualizarBadge();
}
function buildAlertas(){const hoy=new Date(),alerts=[];DB.salud.forEach(s=>{if(!s['ProximaDosis'])return;const d=new Date(s['ProximaDosis']+'T12:00:00'),diff=Math.round((d-hoy)/86400000);if(diff<=30)alerts.push({color:diff<0?'#e53e3e':diff<=7?'#F0A500':'#2E7DD6',icon:diff<0?'🚨':diff<=7?'⚠️':'💉',title:`${diff<0?'VACUNA VENCIDA':'Vacuna próxima'}: ${s['Animal']} — ${s['Descripcion']}`,sub:diff<0?`Venció hace ${-diff} días (${fmt(s['ProximaDosis'])})`:`Vence en ${diff} días (${fmt(s['ProximaDosis'])})`});});DB.insem.forEach(i=>{if(!i['PartoEstimado'])return;const d=new Date(i['PartoEstimado']+'T12:00:00'),diff=Math.round((d-hoy)/86400000);if(diff>=0&&diff<=45)alerts.push({color:'#F0A500',icon:'🐄',title:`Parto próximo: ${i['Hembra']}`,sub:`Fecha estimada: ${fmt(i['PartoEstimado'])} — en ${diff} días`});});return alerts;}
function actualizarBadge(){const n=buildAlertas().length;document.querySelectorAll('[id*="alerta"],.alerta-badge').forEach(b=>{if(b){b.textContent=n;b.style.display=n?'inline-flex':'none';}});}
function renderAlertas(){const alerts=buildAlertas();const sec=document.getElementById('sec-alertas');if(!sec)return;let cont=sec.querySelector('[class*="list"],[id*="list"],[class*="alt-"]');if(!cont){cont=sec.querySelector('div:not([style]):not([class*="header"]):not([class*="hdr"])');if(!cont)return;}if(!alerts.length){cont.innerHTML='<div style="text-align:center;padding:40px;color:#9eaaba;font-size:14px;">✅ ¡Todo en orden! Sin alertas activas.</div>';return;}cont.innerHTML=alerts.map(a=>`<div style="display:flex;gap:12px;padding:14px;border-left:4px solid ${escH(a.color)};background:#fff;border-radius:8px;margin-bottom:6px;border:1px solid #e8edf5;"><div style="font-size:20px">${a.icon}</div><div><div style="font-size:13px;font-weight:600;color:${escH(a.color)}">${escH(a.title)}</div><div style="font-size:12px;color:#9eaaba">${escH(a.sub)}</div></div></div>`).join('');}

