let _filtroEstadoActual='';
function filtrar(q){renderAnimales(q.toLowerCase());}
function filtrarTab(el){document.querySelectorAll('.an-tab').forEach(t=>t.classList.remove('on'));el.classList.add('on');const txt=(el.textContent||'').trim().split(' ')[0];_filtroEstadoActual=txt==='Todos'?'':txt;renderAnimales((document.getElementById('an-buscar')?.value||'').toLowerCase());}

function renderAnimales(q=''){
  const tbody=document.getElementById('an-tbody');if(!tbody)return;
  let list=q?DB.animales.filter(a=>(a['Arete']||'').toLowerCase().includes(q)||(a['Nombre']||'').toLowerCase().includes(q)||(a['Raza']||'').toLowerCase().includes(q)):DB.animales;
  if(_filtroEstadoActual)list=list.filter(a=>(a['Estado']||'')===_filtroEstadoActual);
  const sT=document.getElementById('an-s-total');const sA=document.getElementById('an-s-activos');const sTr=document.getElementById('an-s-trat');const sM=document.getElementById('an-s-muertos');
  if(sT)sT.textContent=DB.animales.length;if(sA)sA.textContent=DB.animales.filter(a=>a['Estado']==='Activo').length;if(sTr)sTr.textContent=DB.animales.filter(a=>a['Estado']==='En tratamiento').length;if(sM)sM.textContent=DB.animales.filter(a=>a['Estado']==='Muerto').length;
  if(!list.length){tbody.innerHTML=`<tr><td colspan="12" style="text-align:center;padding:40px;color:#9eaaba;">${_filtroEstadoActual?'Sin animales con ese estado':'Agrega tu primer animal'}</td></tr>`;return;}
  const estBadge=e=>{const map={'Activo':'an-est-activo','Gestante':'an-est-gestante','En tratamiento':'an-est-activo','Vendido':'an-est-vendido','Muerto':'an-est-muerto'};return`<span class="an-estado-badge ${map[e]||'an-est-activo'}">● ${e||'Activo'}</span>`;};
  tbody.innerHTML=list.map(a=>`<tr style="cursor:pointer" onclick="verFichaAnimal('${a['ID']}')">
    <td><input type="checkbox" onclick="event.stopPropagation()"></td>
    <td class="an-arete">${escH(a['Arete']||'')}</td>
    <td>${a['Foto']?`<img class="an-foto-td" src="${a['Foto']}">`:'<div style="width:32px;height:32px;border-radius:7px;background:#f0f4fa;display:flex;align-items:center;justify-content:center;font-size:16px;">🐄</div>'}</td>
    <td class="an-nombre-bold">${escH(a['Nombre']||'—')}</td>
    <td>${escH(a['Raza']||'')}</td>
    <td><div class="an-sexo" style="color:${a['Sexo']==='Hembra'?'#993556':'#185FA5'}">${a['Sexo']==='Hembra'?'♀ Hembra':'♂ Macho'}</div></td>
    <td>${fmt(a['Nacimiento'])}</td>
    <td>${a['Peso']?a['Peso']+' kg':'—'}</td>
    <td>${escH(a['Madre']||'—')}</td>
    <td>${escH(a['Padre']||'—')}</td>
    <td>${estBadge(a['Estado'])}</td>
    <td onclick="event.stopPropagation()"><div class="an-acc">
      <button class="an-acc-btn ver" onclick="verFichaAnimal('${a['ID']}')"><svg fill="none" stroke="#2E7DD6" stroke-width="2" viewBox="0 0 24 24" width="15" height="15"><path d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/><path d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"/></svg></button>
      <button class="an-acc-btn edit" onclick="editAnimal('${a['ID']}')"><svg fill="none" stroke="#8FA3BF" stroke-width="2" viewBox="0 0 24 24" width="15" height="15"><path d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg></button>
      <button class="an-acc-btn del" onclick="delAnimal('${a['ID']}')"><svg fill="none" stroke="#E24B4A" stroke-width="2" viewBox="0 0 24 24" width="15" height="15"><path d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg></button>
    </div></td></tr>`).join('');
}

function abrirModalAnimal(){['a-arete','a-nombre','a-obs','a-nac','a-peso'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});['a-raza','a-sexo','a-estado','a-padre-sel','a-madre-sel'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});const editId=document.getElementById('a-edit-id');if(editId)editId.value='';const padre=document.getElementById('a-padre');if(padre){padre.value='';padre.style.display='none';}const madre=document.getElementById('a-madre');if(madre){madre.value='';madre.style.display='none';}const prev=document.getElementById('a-photo-preview');if(prev)prev.innerHTML='<span style="font-size:28px">📸</span><span>Cámara o galería</span>';const photo=document.getElementById('a-photo');if(photo)photo.value='';const title=document.getElementById('m-animal-title');if(title)title.innerHTML='🐂 Registrar Animal <span style="float:right;cursor:pointer;color:#9eaaba;font-size:22px;font-weight:400;" onclick="closeM(\'m-animal\')">×</span>';const estado=document.getElementById('a-estado');if(estado)estado.value='Activo';poblarListasPadresMadres();openM('m-animal');}

function verFichaAnimal(id){
  const a=DB.animales.find(x=>String(x['ID'])===String(id));if(!a)return;
  function calcEdad(nac){if(!nac)return'—';const d=new Date(nac+'T12:00:00');if(isNaN(d))return'—';const dias=Math.floor((new Date()-d)/86400000);if(dias<30)return dias+' días';const meses=Math.floor(dias/30.44);if(meses<12)return meses+' mes'+(meses!==1?'es':'');const años=Math.floor(meses/12),mr=meses%12;return años+' año'+(años!==1?'s':'')+(mr>0?' '+mr+' mes'+(mr!==1?'es':''):'');}
  const contenido=document.getElementById('ficha-animal-content');const foto=a['Foto']||'';
  contenido.innerHTML=`<div style="display:flex;align-items:center;gap:14px;margin-bottom:18px"><div style="width:72px;height:72px;border-radius:14px;overflow:hidden;border:2px solid #e8edf5;flex-shrink:0;display:flex;align-items:center;justify-content:center;background:#f8fafc;font-size:36px">${foto?`<img src="${foto}" style="width:100%;height:100%;object-fit:cover">`:'🐄'}</div><div><div style="font-size:22px;font-weight:800;color:#2E7DD6;font-family:'Montserrat',sans-serif;">${escH(a['Arete']||'')}</div><div style="font-size:14px;color:#5A6A85;">${escH(a['Nombre']||'Sin nombre')}</div><span style="display:inline-block;margin-top:5px;background:${a['Estado']==='Activo'?'#e8f5e9':'#fff3e0'};color:${a['Estado']==='Activo'?'#1b8e4e':'#e07b00'};border-radius:20px;padding:2px 10px;font-size:12px;font-weight:600;">${a['Estado']||''}</span></div></div>
  <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">${[['Raza',a['Raza']||'—'],['Sexo',(a['Sexo']==='Hembra'?'♀ ':'♂ ')+(a['Sexo']||'—')],['Edad',calcEdad(a['Nacimiento'])],['Peso',a['Peso']?a['Peso']+' kg':'—'],['Madre',a['Madre']||'—'],['Padre',a['Padre']||'—']].map(([l,val])=>`<div style="background:#f8fafc;border:1px solid #e8edf5;border-radius:10px;padding:10px 13px"><div style="font-size:9px;color:#2E7DD6;font-weight:700;text-transform:uppercase;letter-spacing:1px;margin-bottom:4px">${l}</div><div style="font-size:14px;font-weight:600;color:#0D2B6B">${escH(val)}</div></div>`).join('')}</div>
  ${a['Observaciones']?`<div style="margin-top:10px;background:#f8fafc;border:1px solid #e8edf5;border-radius:10px;padding:10px 13px"><div style="font-size:9px;color:#2E7DD6;font-weight:700;text-transform:uppercase;margin-bottom:4px">Observaciones</div><div style="font-size:13px;color:#5A6A85">${escH(a['Observaciones'])}</div></div>`:''}
  <div style="margin-top:16px;display:flex;gap:8px;justify-content:flex-end"><button onclick="closeM('m-ficha-animal');editAnimal('${a['ID']}')" style="padding:9px 16px;border-radius:9px;border:1.5px solid #dde3ec;background:#fff;color:#4a5568;font-size:13px;font-weight:600;cursor:pointer;">✏️ Editar</button><button onclick="closeM('m-ficha-animal')" style="padding:9px 18px;border-radius:9px;border:none;background:#2E7DD6;color:#fff;font-size:13px;font-weight:600;cursor:pointer;">Cerrar</button></div>`;
  const titulo=document.getElementById('ficha-animal-titulo');if(titulo)titulo.textContent=(a['Arete']||'')+(a['Nombre']?' — '+a['Nombre']:'');
  openM('m-ficha-animal');
}

function editAnimal(id){const a=DB.animales.find(x=>String(x['ID'])===String(id));if(!a)return;document.getElementById('a-edit-id').value=id;document.getElementById('a-arete').value=a['Arete']||'';document.getElementById('a-nombre').value=a['Nombre']||'';document.getElementById('a-raza').value=a['Raza']||'';document.getElementById('a-sexo').value=a['Sexo']||'';document.getElementById('a-nac').value=a['Nacimiento']||'';document.getElementById('a-peso').value=a['Peso']||'';document.getElementById('a-estado').value=a['Estado']||'Activo';document.getElementById('a-obs').value=a['Observaciones']||'';const foto=a['Foto']||'';document.getElementById('a-photo').value=foto;const prev=document.getElementById('a-photo-preview');if(foto)prev.innerHTML=`<img src="${foto}" style="width:100%;height:100%;object-fit:cover;border-radius:10px">`;else prev.innerHTML='<span style="font-size:28px">📸</span><span>Cámara o galería</span>';const title=document.getElementById('m-animal-title');if(title)title.innerHTML='✏️ Editar Animal <span style="float:right;cursor:pointer;color:#9eaaba;font-size:22px;font-weight:400;" onclick="closeM(\'m-animal\')">×</span>';poblarListasPadresMadres();const padreVal=a['Padre']||'';const padreSelEl=document.getElementById('a-padre-sel');const padreInpEl=document.getElementById('a-padre');if(padreSelEl&&padreInpEl){const existe=Array.from(padreSelEl.options).some(o=>o.value===padreVal);if(padreVal&&!existe){padreSelEl.value='__manual__';padreInpEl.style.display='';padreInpEl.value=padreVal;}else{padreSelEl.value=padreVal;padreInpEl.style.display='none';padreInpEl.value=padreVal;}}const madreVal=a['Madre']||'';const madreSelEl=document.getElementById('a-madre-sel');const madreInpEl=document.getElementById('a-madre');if(madreSelEl&&madreInpEl){const existe=Array.from(madreSelEl.options).some(o=>o.value===madreVal);if(madreVal&&!existe){madreSelEl.value='__manual__';madreInpEl.style.display='';madreInpEl.value=madreVal;}else{madreSelEl.value=madreVal;madreInpEl.style.display='none';madreInpEl.value=madreVal;}}openM('m-animal');}

async function saveAnimal(){const arete=v('a-arete'),raza=v('a-raza'),sexo=v('a-sexo');if(!arete||!raza||!sexo){toast('⚠️ Completa los campos obligatorios (*)');return;}const editId=document.getElementById('a-edit-id').value;const _n=v('a-nombre'),_nac=v('a-nac'),_p=document.getElementById('a-peso')?.value?.trim()||'',_e=v('a-estado')||'Activo';let _padre=v('a-padre');if(!_padre||_padre==='__manual__')_padre=v('a-padre-sel');if(_padre==='__manual__')_padre='';let _madre=v('a-madre');if(!_madre||_madre==='__manual__')_madre=v('a-madre-sel');if(_madre==='__manual__')_madre='';const _obs=v('a-obs');const btn=document.getElementById('btn-save-animal');if(btn){btn.innerHTML='⏳ Guardando...';btn.disabled=true;}setSyncStatus('syncing','🔄 Guardando...');const foto=document.getElementById('a-photo')?.value||'';const animalId=editId||String(Date.now());if(foto)localStorage.setItem('vqa_foto_'+animalId,foto);const row={'Arete':arete,'Nombre':_n,'Raza':raza,'Sexo':sexo,'Nacimiento':_nac,'Peso':_p?parseFloat(_p):null,'Estado':_e,'Madre':_madre,'Padre':_padre,'Observaciones':_obs,'Foto':foto.startsWith('https://')?foto:''};const rowDisplay={...row,'ID':animalId,'Peso(kg)':_p,'Foto':foto,'rancho_id':SESSION?.rancho_id||null};try{if(editId){apiPostFast('update','animales',row,editId);const idx=DB.animales.findIndex(x=>String(x['ID'])===String(editId));if(idx>=0)DB.animales[idx]={...DB.animales[idx],...rowDisplay};toast('✅ Animal actualizado');}else{apiPostFast('insert','animales',row);DB.animales.unshift(rowDisplay);toast('✅ Animal guardado');}setSyncStatus('ok','☁ Sincronizado');renderAnimales();renderDash();poblarListasPadresMadres();closeM('m-animal');}catch(e){setSyncStatus('err','❌ Error');toast('❌ Error al guardar');}if(btn){btn.innerHTML='💾 Guardar';btn.disabled=false;}}

async function delAnimal(id){if(!confirm('¿Eliminar este animal?'))return;setSyncStatus('syncing','🔄 Eliminando...');apiPostFast('delete','animales',null,id);DB.animales=DB.animales.filter(a=>String(a['ID'])!==String(id));renderAnimales();renderDash();poblarListasPadresMadres();setSyncStatus('ok','☁ Sincronizado');toast('🗑 Animal eliminado');}

function poblarListasPadresMadres(){const oS=document.getElementById('opt-padre-semen');const oM=document.getElementById('opt-padre-machos');const oH=document.getElementById('opt-madre-hembras');if(oS)oS.innerHTML=(DB.semen_toros||[]).map(t=>`<option value="SEMEN:${t.ID}">🐂 ${escH(t.Nombre)} (${escH(t.Raza)}) · ${t.Pajillas} paj.</option>`).join('');if(oM)oM.innerHTML=DB.animales.filter(a=>a['Sexo']==='Macho'&&a['Estado']!=='Muerto'&&a['Estado']!=='Vendido').map(a=>`<option value="${escH(a['Arete']||'')}">${escH(a['Arete']||'')} ${a['Nombre']?'— '+escH(a['Nombre']):''}</option>`).join('');if(oH)oH.innerHTML=DB.animales.filter(a=>a['Sexo']==='Hembra'&&a['Estado']!=='Muerto'&&a['Estado']!=='Vendido').map(a=>`<option value="${escH(a['Arete']||'')}">${escH(a['Arete']||'')} ${a['Nombre']?'— '+escH(a['Nombre']):''}</option>`).join('');}

function syncPadreInput(){const sel=document.getElementById('a-padre-sel'),inp=document.getElementById('a-padre');if(!sel||!inp)return;if(sel.value==='__manual__'){inp.style.display='';inp.focus();inp.value='';}else if(sel.value.startsWith('SEMEN:')){const toroID=sel.value.replace('SEMEN:','');const toro=(DB.semen_toros||[]).find(t=>t.ID===toroID);inp.style.display='none';inp.value=toro?`${toro.Nombre} (${toro.Raza})`:'';inp.dataset.toroId=toroID;}else{inp.style.display='none';inp.value=sel.value;}}
function syncMadreInput(){const sel=document.getElementById('a-madre-sel'),inp=document.getElementById('a-madre');if(!sel||!inp)return;if(sel.value==='__manual__'){inp.style.display='';inp.focus();inp.value='';}else{inp.style.display='none';inp.value=sel.value;}}
function previewAnimalPhoto(input){if(!input.files||!input.files[0])return;const reader=new FileReader();reader.onload=e=>{const data=e.target.result;const prev=document.getElementById('a-photo-preview');const photo=document.getElementById('a-photo');if(prev)prev.innerHTML=`<img src="${data}" style="width:100%;height:100%;object-fit:cover;border-radius:10px">`;if(photo)photo.value=data;};reader.readAsDataURL(input.files[0]);}

// ══ SALUD ══
function fillSelects(){['s-animal','i-hembra'].forEach(id=>{const el=document.getElementById(id);if(!el)return;const onlyF=id==='i-hembra';el.innerHTML='<option value="">Seleccionar...</option>'+DB.animales.filter(a=>!onlyF||a['Sexo']==='Hembra').map(a=>`<option value="${escH(a['Arete'])}">${escH(a['Arete'])}${a['Nombre']?' — '+escH(a['Nombre']):''}</option>`).join('');});}

async function saveSalud(){const animal=v('s-animal'),tipo=v('s-tipo'),desc=v('s-desc'),fecha=v('s-fecha');if(!animal||!tipo||!desc||!fecha){toast('⚠️ Completa los campos obligatorios (*)');return;}setSyncStatus('syncing','🔄 Guardando...');const row={'ID':Date.now(),'Animal':animal,'Tipo':tipo,'Descripcion':desc,'Dosis':v('s-dosis'),'FechaAplicacion':fecha,'ProximaDosis':v('s-prox'),'Veterinario':v('s-vet'),'Costo':v('s-costo'),'Observaciones':v('s-obs')};apiPostFast('insert','salud',row);DB.salud.unshift(row);renderSalud();actualizarBadge();closeM('m-salud');clearF(['s-animal','s-tipo','s-desc','s-dosis','s-fecha','s-prox','s-vet','s-costo','s-obs']);setSyncStatus('ok','☁ Sincronizado');toast('✅ Registro de salud guardado');}

function renderSalud(){const tbody=document.getElementById('sv-tbody');if(!tbody)return;const hoy=new Date();if(!DB.salud.length){tbody.innerHTML='<tr><td colspan="8" style="text-align:center;padding:40px;color:#9eaaba;">💉 Sin registros de salud</td></tr>';return;}tbody.innerHTML=DB.salud.map(r=>{let est='Aplicado',cls='#1b8e4e',bg='#e8f5e9';if(r['ProximaDosis']){const d=new Date(r['ProximaDosis']+'T12:00:00'),diff=Math.round((d-hoy)/86400000);if(diff<0){est='Vencido';cls='#e53e3e';bg='#fce8e8';}else if(diff<=15){est='Por vencer';cls='#e07b00';bg='#fff3e0';}}return`<tr><td><strong style="color:#2E7DD6">${escH(r['Animal']||'')}</strong></td><td>${escH(r['Tipo']||'')}</td><td>${escH(r['Descripcion']||'')}</td><td>${fmt(r['FechaAplicacion'])}</td><td>${r['ProximaDosis']?fmt(r['ProximaDosis']):'—'}</td><td>${escH(r['Veterinario']||'—')}</td><td><span style="background:${bg};color:${cls};border-radius:20px;font-size:11px;font-weight:600;padding:3px 10px;">${est}</span></td><td><button onclick="delSalud('${r['ID']}')" style="background:#fce8e8;color:#e53e3e;border:none;border-radius:7px;padding:5px 9px;cursor:pointer;font-size:12px;">🗑</button></td></tr>`;}).join('');const sT=document.getElementById('sv-s-total'),sA=document.getElementById('sv-s-aplicadas');if(sT)sT.textContent=DB.salud.length;if(sA)sA.textContent=DB.salud.filter(s=>!s['ProximaDosis']||new Date(s['ProximaDosis']+'T12:00:00')>=new Date()).length;}
async function delSalud(id){if(!confirm('¿Eliminar?'))return;apiPostFast('delete','salud',null,id);DB.salud=DB.salud.filter(r=>String(r['ID'])!==String(id));renderSalud();actualizarBadge();toast('🗑 Eliminado');}

// ══ INSEMINACIÓN ══
function calcParto(){const f=v('i-fecha');if(!f)return;const d=new Date(f+'T12:00:00');d.setDate(d.getDate()+283);document.getElementById('i-parto').value=d.toISOString().split('T')[0];}
function poblarSelectInsemToro(){const sel=document.getElementById('i-toro-sel'),inp=document.getElementById('i-toro'),stock=document.getElementById('i-toro-stock');if(!sel)return;if(sel.value==='__manual__'){if(inp)inp.style.display='block';if(stock)stock.style.display='none';return;}if(!sel.value){if(inp)inp.style.display='none';return;}const toroID=sel.value.replace('SEMEN:','');const toro=(DB.semen_toros||[]).find(t=>t.ID===toroID);if(inp){inp.style.display='none';inp.value=toro?`${toro.Nombre} (${toro.Raza})`:'';inp.dataset.toroId=toroID;}if(stock&&toro){stock.style.display='block';stock.textContent=`${toro.Pajillas} pajillas disponibles`;}}
function editInsem(id){const r=DB.insem.find(x=>String(x['ID'])===String(id));if(!r)return;document.getElementById('i-edit-id').value=id;document.getElementById('insem-modal-titulo').innerHTML='✏️ Editar Inseminación <span style="float:right;cursor:pointer;color:#9eaaba;font-size:22px;font-weight:400;" onclick="closeM(\'m-insem\')">×</span>';document.getElementById('insem-save-btn').textContent='💾 Actualizar';openM('m-insem');setTimeout(()=>{fillSelects();const hEl=document.getElementById('i-hembra');if(hEl){let optE=Array.from(hEl.options).some(o=>o.value===r['Hembra']);if(!optE&&r['Hembra']){const opt=document.createElement('option');opt.value=r['Hembra'];opt.textContent=r['Hembra'];hEl.appendChild(opt);}hEl.value=r['Hembra']||'';}document.getElementById('i-fecha').value=r['Fecha']||'';const toroInp=document.getElementById('i-toro');const toroSel=document.getElementById('i-toro-sel');if(toroInp){toroInp.value=r['ToroSemen']||'';toroInp.style.display='block';}if(toroSel)toroSel.value='__manual__';const tS=document.getElementById('i-toro-stock');if(tS)tS.style.display='none';const tec=document.getElementById('i-tec');if(tec)tec.value=r['Tecnica']||'Inseminación Artificial (IA)';document.getElementById('i-tecnico').value=r['Tecnico']||'';document.getElementById('i-parto').value=r['PartoEstimado']||'';const res=document.getElementById('i-res');if(res)res.value=r['Resultado']||'Pendiente';document.getElementById('i-costo').value=r['Costo']||'';document.getElementById('i-obs').value=r['Observaciones']||'';},60);}
async function saveInsem(){const editId=v('i-edit-id'),hembra=v('i-hembra'),fecha=v('i-fecha'),toro=v('i-toro');if(!hembra||!fecha||!toro){toast('⚠️ Completa los campos obligatorios (*)');return;}setSyncStatus('syncing','🔄 Guardando...');const res=v('i-res');if(editId){const idx=DB.insem.findIndex(x=>String(x['ID'])===String(editId));if(idx===-1){toast('❌ No encontrado');return;}const upd={...DB.insem[idx],'Hembra':hembra,'Fecha':fecha,'ToroSemen':toro,'Tecnica':v('i-tec'),'Tecnico':v('i-tecnico'),'PartoEstimado':v('i-parto'),'Resultado':res,'Costo':v('i-costo'),'Observaciones':v('i-obs')};DB.insem[idx]=upd;apiPostFast('update','insem',upd,editId);if(res==='Preñada ✓'){const a=DB.animales.find(x=>x['Arete']===hembra);if(a&&a['Estado']!=='Gestante'){a['Estado']='Gestante';apiPostFast('update','animales',a,a['ID']);renderAnimales();}}renderInsem();renderDash();closeM('m-insem');resetInsemModal();toast('✅ Inseminación actualizada');setSyncStatus('ok','☁ Sincronizado');return;}const row={'ID':Date.now(),'Hembra':hembra,'Fecha':fecha,'ToroSemen':toro,'Tecnica':v('i-tec'),'Tecnico':v('i-tecnico'),'PartoEstimado':v('i-parto'),'Resultado':res,'Costo':v('i-costo'),'Observaciones':v('i-obs')};apiPostFast('insert','insem',row);DB.insem.unshift(row);if(res==='Preñada ✓'){const a=DB.animales.find(x=>x['Arete']===hembra);if(a){a['Estado']='Gestante';apiPostFast('update','animales',a,a['ID']);renderAnimales();}}renderInsem();renderDash();closeM('m-insem');resetInsemModal();setSyncStatus('ok','☁ Sincronizado');toast('✅ Inseminación guardada');}
function resetInsemModal(){document.getElementById('i-edit-id').value='';document.getElementById('insem-modal-titulo').innerHTML='🔬 Registrar Inseminación <span style="float:right;cursor:pointer;color:#9eaaba;font-size:22px;font-weight:400;" onclick="closeM(\'m-insem\')">×</span>';document.getElementById('insem-save-btn').textContent='💾 Guardar';clearF(['i-hembra','i-fecha','i-tecnico','i-parto','i-costo','i-obs']);try{document.getElementById('i-toro-sel').value='';document.getElementById('i-toro').value='';document.getElementById('i-toro').style.display='none';document.getElementById('i-toro-stock').style.display='none';}catch(e){}}
function renderInsem(){const tbody=document.getElementById('in-tbody');if(!tbody)return;if(!DB.insem.length){tbody.innerHTML='<tr><td colspan="8" style="text-align:center;padding:40px;color:#9eaaba;">🔬 Sin registros</td></tr>';return;}const resSelect=(id,val)=>`<select style="background:#f8fafc;border:1px solid #e8edf5;border-radius:6px;color:#0D2B6B;padding:4px 8px;font-size:11px;font-weight:600;cursor:pointer;width:100%;" onchange="updateResultadoInsem('${id}',this.value)"><option value="Pendiente" ${(val||'Pendiente')==='Pendiente'?'selected':''}>⏳ Pendiente</option><option value="Preñada ✓" ${val==='Preñada ✓'?'selected':''}>✅ Preñada</option><option value="Vacía ✗" ${val==='Vacía ✗'?'selected':''}>❌ Vacía</option><option value="Repetición" ${val==='Repetición'?'selected':''}>🔄 Repetición</option></select>`;tbody.innerHTML=DB.insem.map(r=>`<tr><td><strong style="color:#2E7DD6">${escH(r['Hembra']||'')}</strong></td><td>${fmt(r['Fecha'])}</td><td>${escH(r['ToroSemen']||'')}</td><td>${escH(r['Tecnica']||'')}</td><td>${escH(r['Tecnico']||'—')}</td><td>${r['PartoEstimado']?fmt(r['PartoEstimado']):'—'}</td><td>${resSelect(r['ID'],r['Resultado'])}</td><td style="display:flex;gap:4px;"><button onclick="editInsem('${r['ID']}')" style="background:#e8f0fc;color:#2E7DD6;border:none;border-radius:7px;padding:5px 9px;cursor:pointer;font-size:12px;">✏️</button><button onclick="delInsem('${r['ID']}')" style="background:#fce8e8;color:#e53e3e;border:none;border-radius:7px;padding:5px 9px;cursor:pointer;font-size:12px;">🗑</button></td></tr>`).join('');}
async function updateResultadoInsem(id,resultado){const ins=DB.insem.find(r=>String(r['ID'])===String(id));if(!ins)return;ins['Resultado']=resultado;apiPostFast('update','insem',ins,id);if(resultado==='Preñada ✓'){const a=DB.animales.find(x=>x['Arete']===ins['Hembra']);if(a&&a['Estado']!=='Gestante'){a['Estado']='Gestante';apiPostFast('update','animales',a,a['ID']);renderAnimales();renderDash();}}else if(resultado==='Vacía ✗'||resultado==='Repetición'){const a=DB.animales.find(x=>x['Arete']===ins['Hembra']);if(a&&a['Estado']==='Gestante'){a['Estado']='Activo';apiPostFast('update','animales',a,a['ID']);renderAnimales();renderDash();}}toast('✅ Resultado actualizado');}
async function delInsem(id){if(!confirm('¿Eliminar?'))return;apiPostFast('delete','insem',null,id);DB.insem=DB.insem.filter(r=>String(r['ID'])!==String(id));renderInsem();renderDash();toast('🗑 Eliminado');}

// ══ PARTOS ══
function fillSelectMadres(){const el=document.getElementById('pt-madre');if(!el)return;el.innerHTML='<option value="">Seleccionar madre...</option>'+DB.animales.filter(a=>a['Sexo']==='Hembra').map(a=>`<option value="${escH(a['Arete'])}">${escH(a['Arete'])}${a['Nombre']?' — '+escH(a['Nombre']):''}</option>`).join('');}
async function saveParto(){const fecha=v('pt-fecha'),madre=v('pt-madre');if(!fecha||!madre){toast('⚠️ Completa los campos obligatorios (*)');return;}setSyncStatus('syncing','🔄 Guardando...');const row={'ID':Date.now(),'Fecha':fecha,'Madre':madre,'ArieteCria':v('pt-arete-cria'),'SexoCria':v('pt-sexo-cria'),'PesoNacimiento':v('pt-peso')?parseFloat(v('pt-peso')):null,'TipoParto':v('pt-tipo')||'Natural','EstadoCria':v('pt-estado-cria')||'Vivo','Padre':v('pt-padre'),'Observaciones':v('pt-obs')};apiPostFast('insert','partos',row);DB.partos.unshift(row);if(row['EstadoCria']==='Vivo'){const a=DB.animales.find(x=>x['Arete']===madre);if(a&&a['Estado']==='Gestante'){a['Estado']='Activo';apiPostFast('update','animales',a,a['ID']);renderAnimales();}}renderPartos();closeM('m-parto');clearF(['pt-fecha','pt-arete-cria','pt-peso','pt-padre','pt-obs']);setSyncStatus('ok','☁ Sincronizado');toast('✅ Parto registrado');}
function renderPartos(){const tbody=document.getElementById('pt-tbody');if(!tbody)return;if(!DB.partos.length){tbody.innerHTML='<tr><td colspan="9" style="text-align:center;padding:40px;color:#9eaaba;">🐣 Sin registros de partos</td></tr>';return;}tbody.innerHTML=DB.partos.map(r=>`<tr><td>${fmt(r['Fecha'])}</td><td><strong style="color:#2E7DD6">${escH(r['Madre']||'')}</strong></td><td>${escH(r['ArieteCria']||'—')}</td><td>${r['SexoCria']?`<span style="color:${r['SexoCria']==='Hembra'?'#993556':'#185FA5'}">${r['SexoCria']==='Hembra'?'♀':'♂'} ${r['SexoCria']}</span>`:'—'}</td><td>${r['PesoNacimiento']?r['PesoNacimiento']+' kg':'—'}</td><td>${escH(r['TipoParto']||'—')}</td><td>${escH(r['EstadoCria']||'—')}</td><td>${escH(r['Padre']||'—')}</td><td><button onclick="delParto('${r['ID']}')" style="background:#fce8e8;color:#e53e3e;border:none;border-radius:7px;padding:5px 9px;cursor:pointer;font-size:12px;">🗑</button></td></tr>`).join('');}
async function delParto(id){if(!confirm('¿Eliminar?'))return;apiPostFast('delete','partos',null,id);DB.partos=DB.partos.filter(r=>String(r['ID'])!==String(id));renderPartos();toast('🗑 Eliminado');}

// ══ GASTOS ══
function fillGastoAnimales(){const el=document.getElementById('g-animal');if(!el)return;el.innerHTML='<option value="">Sin animal específico</option>'+DB.animales.map(a=>`<option value="${escH(a['Arete'])}">${escH(a['Arete'])}${a['Nombre']?' — '+escH(a['Nombre']):''}</option>`).join('');}
async function saveGasto(){const monto=v('g-monto'),fecha=v('g-fecha');if(!monto||!fecha){toast('⚠️ Monto y fecha son obligatorios');return;}setSyncStatus('syncing','🔄 Guardando...');const esIng=document.getElementById('g-esIngreso')?.value==='true';const row={'ID':Date.now(),'Tipo':v('g-tipo'),'Descripcion':v('g-desc'),'Monto':parseFloat(monto),'EsIngreso':esIng,'Fecha':fecha,'Animal':v('g-animal'),'Observaciones':v('g-obs')};apiPostFast('insert','gastos',row);DB.gastos.unshift(row);renderGastos();closeM('m-gasto');clearF(['g-desc','g-monto','g-fecha','g-obs']);setSyncStatus('ok','☁ Sincronizado');toast('✅ Movimiento guardado');}
function renderGastos(){const tbody=document.getElementById('gas-tbody');const fmtM=n=>'S/ '+parseFloat(n||0).toLocaleString('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2});const esIng=g=>{const val=String(g['EsIngreso']||'').toUpperCase();return val==='TRUE'||val==='SI'||val==='1';};const tI=DB.gastos.filter(g=>esIng(g)).reduce((s,g)=>s+parseFloat(g['Monto']||0),0);const tG=DB.gastos.filter(g=>!esIng(g)).reduce((s,g)=>s+parseFloat(g['Monto']||0),0);['g-ingresos','g-gastos','g-balance'].forEach((id,i)=>{const el=document.getElementById(id);if(!el)return;if(i===0)el.textContent=fmtM(tI);else if(i===1)el.textContent=fmtM(tG);else{el.textContent=fmtM(tI-tG);el.style.color=tI-tG>=0?'#1b8e4e':'#e53e3e';}});if(tbody){if(!DB.gastos.length){tbody.innerHTML='<tr><td colspan="6" style="text-align:center;padding:40px;color:#9eaaba;">Sin movimientos registrados</td></tr>';return;}tbody.innerHTML=DB.gastos.map(g=>{const ei=esIng(g);return`<tr><td>${fmt(g['Fecha'])}</td><td>${escH(g['Tipo']||'')}</td><td>${escH(g['Descripcion']||'')}</td><td><strong style="color:${ei?'#1b8e4e':'#e53e3e'}">${ei?'+':'-'}${fmtM(g['Monto'])}</strong></td><td>${escH(g['Animal']||'—')}</td><td><button onclick="delGasto('${g['ID']}')" style="background:#fce8e8;color:#e53e3e;border:none;border-radius:7px;padding:5px 9px;cursor:pointer;font-size:12px;">🗑</button></td></tr>`;}).join('');}}
async function delGasto(id){if(!confirm('¿Eliminar?'))return;apiPostFast('delete','gastos',null,id);DB.gastos=DB.gastos.filter(g=>String(g['ID'])!==String(id));renderGastos();toast('🗑 Eliminado');}

// ══ INVENTARIO ══
function renderInventario(){const tbody=document.getElementById('inv-tbody');if(!tbody)return;if(!DB.inventario.length){tbody.innerHTML='<tr><td colspan="8" style="text-align:center;padding:40px;color:#9eaaba;">Sin productos en inventario</td></tr>';return;}tbody.innerHTML=DB.inventario.map(r=>`<tr><td><strong>${escH(r['Nombre']||'')}</strong></td><td>${escH(r['Categoria']||'')}</td><td>${r['Stock']||0} ${escH(r['Unidad']||'')}</td><td>${r['Minimo']||0}</td><td>${r['Precio']?'S/ '+parseFloat(r['Precio']).toFixed(2):'—'}</td><td>${escH(r['Proveedor']||'—')}</td><td>${r['Vencimiento']?fmt(r['Vencimiento']):'—'}</td><td><span style="background:${parseInt(r['Stock']||0)<=parseInt(r['Minimo']||0)?'#fce8e8':'#e8f5e9'};color:${parseInt(r['Stock']||0)<=parseInt(r['Minimo']||0)?'#e53e3e':'#1b8e4e'};border-radius:20px;font-size:11px;font-weight:600;padding:3px 8px;">${parseInt(r['Stock']||0)<=parseInt(r['Minimo']||0)?'⚠ Stock bajo':'OK'}</span></td></tr>`).join('');}

// ══ HISTORIAL ══
function renderHistorialCards(lista){const sec=document.getElementById('sec-historial');if(!sec)return;let cont=sec.querySelector('.hist-lista,.hist-cards');if(!cont){cont=document.createElement('div');cont.className='hist-lista';cont.style.cssText='padding:16px;display:flex;flex-direction:column;gap:8px;overflow-y:auto;flex:1;';sec.appendChild(cont);}if(!lista||!lista.length){cont.innerHTML='<div style="text-align:center;padding:40px;color:#9eaaba;">Sin animales registrados</div>';return;}cont.innerHTML=lista.map(a=>`<div style="background:#fff;border:1px solid #e8edf5;border-radius:12px;padding:14px 16px;cursor:pointer;display:flex;align-items:center;gap:12px;" onclick="openHistorialAnimal('${a['ID']}')">${a['Foto']?`<img src="${a['Foto']}" style="width:44px;height:44px;border-radius:10px;object-fit:cover;flex-shrink:0;">`:'<div style="width:44px;height:44px;border-radius:10px;background:#f8fafc;display:flex;align-items:center;justify-content:center;font-size:22px;flex-shrink:0;">🐄</div>'}<div style="flex:1"><div style="font-weight:700;color:#2E7DD6;font-size:14px;">${escH(a['Arete']||'')} ${a['Nombre']?'— '+escH(a['Nombre']):''}</div><div style="font-size:12px;color:#9eaaba;">${escH(a['Raza']||'')} | ${a['Sexo']==='Hembra'?'♀ Hembra':'♂ Macho'}</div></div><span style="background:${a['Estado']==='Activo'?'#e8f5e9':'#fff3e0'};color:${a['Estado']==='Activo'?'#1b8e4e':'#e07b00'};border-radius:20px;font-size:11px;font-weight:600;padding:3px 9px;">${a['Estado']||''}</span><span style="color:#9eaaba;font-size:18px;">›</span></div>`).join('');}
function filtrarHistorial(q){renderHistorialCards(DB.animales.filter(a=>(a['Arete']||'').toLowerCase().includes(q.toLowerCase())||(a['Nombre']||'').toLowerCase().includes(q.toLowerCase())));}
function openHistorialAnimal(id){const a=DB.animales.find(x=>String(x['ID'])===String(id));if(!a)return;const eventos=[];DB.salud.filter(s=>s['Animal']===a['Arete']).forEach(s=>eventos.push({fecha:s['FechaAplicacion']||'',tipo:'💉 Salud/Vacuna',desc:`${s['Tipo']||''} — ${s['Descripcion']||''}`,sub:`Dosis: ${s['Dosis']||'—'} | Próxima: ${s['ProximaDosis']?fmt(s['ProximaDosis']):'—'}`,color:'#2E7DD6'}));DB.insem.filter(i=>i['Hembra']===a['Arete']).forEach(i=>eventos.push({fecha:i['Fecha']||'',tipo:'🔬 Inseminación',desc:`Toro: ${i['ToroSemen']||'—'} | ${i['Tecnica']||'—'}`,sub:`Resultado: ${i['Resultado']||'Pendiente'} | Parto est.: ${i['PartoEstimado']?fmt(i['PartoEstimado']):'—'}`,color:'#F0A500'}));DB.partos.filter(p=>p['Madre']===a['Arete']).forEach(p=>eventos.push({fecha:p['Fecha']||'',tipo:'🐣 Parto',desc:`Cría: ${p['ArieteCria']||'—'} (${p['SexoCria']||'—'}) | Peso: ${p['PesoNacimiento']?p['PesoNacimiento']+' kg':'—'}`,sub:`Tipo: ${p['TipoParto']||'—'} | Estado cría: ${p['EstadoCria']||'—'}`,color:'#22a96a'}));eventos.sort((a,b)=>new Date(b.fecha)-new Date(a.fecha));document.getElementById('m-hist-title').innerHTML=`📅 ${escH(a['Arete'])} ${a['Nombre']?'— '+escH(a['Nombre']):''} <span onclick="closeM('m-historial-animal')" style="float:right;cursor:pointer;color:#9eaaba;font-size:22px;font-weight:400;">×</span>`;const mc=document.getElementById('m-hist-content');mc.innerHTML=`<div style="display:flex;align-items:center;gap:12px;padding:12px;border-bottom:1px solid #f0f4fa;margin-bottom:12px;">${a['Foto']?`<img src="${a['Foto']}" style="width:44px;height:44px;border-radius:10px;object-fit:cover;">`:'<div style="font-size:34px">🐄</div>'}<div><div style="font-size:16px;font-weight:700;color:#2E7DD6;">${escH(a['Arete'])} ${a['Nombre']?'— '+escH(a['Nombre']):''}</div><div style="font-size:12px;color:#9eaaba;">${escH(a['Raza']||'')} | ${a['Sexo']||''}</div></div><div style="margin-left:auto;text-align:center"><div style="font-size:22px;font-weight:700;color:#2E7DD6">${eventos.length}</div><div style="font-size:10px;color:#9eaaba;">eventos</div></div></div>`+(eventos.length?eventos.map(ev=>`<div style="display:flex;gap:10px;padding:10px 0;border-bottom:1px solid #f0f4fa;border-left:3px solid ${ev.color};padding-left:10px;margin-bottom:4px;"><div style="flex:1"><div style="display:flex;justify-content:space-between;"><span style="font-size:12px;font-weight:700;color:${ev.color}">${escH(ev.tipo)}</span><span style="font-size:11px;color:#9eaaba">${ev.fecha?fmt(ev.fecha):'—'}</span></div><div style="font-size:13px;color:#0D2B6B;margin-top:2px">${escH(ev.desc)}</div><div style="font-size:11px;color:#9eaaba;margin-top:2px">${escH(ev.sub)}</div></div></div>`).join(''):'<div style="text-align:center;padding:30px;color:#9eaaba;font-size:13px;">Sin registros para este animal</div>');openM('m-historial-animal');}

// ══ CALENDARIO ══
const MESES=['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
const DS=['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'];
function shiftMes(d){calMes+=d;if(calMes>11){calMes=0;calAno++;}if(calMes<0){calMes=11;calAno--;}renderCalendario();}
function renderCalendario(){const titulo=document.getElementById('cal-mes-titulo'),grid=document.getElementById('cal-grid');if(!titulo||!grid)return;titulo.textContent=MESES[calMes]+' '+calAno;const hoy=new Date();const evMap={};const p=(k,val)=>{if(!k)return;const key=k.substring(0,10);if(!evMap[key])evMap[key]=[];evMap[key].push(val);};DB.insem.forEach(i=>{if(i['Fecha'])p(i['Fecha'],{icon:'🔬',color:'#2E7DD6',txt:`Insem: ${i['Hembra']||''}`});if(i['PartoEstimado'])p(i['PartoEstimado'],{icon:'🐄',color:'#F0A500',txt:`Parto est.: ${i['Hembra']||''}`});});DB.salud.forEach(s=>{if(s['ProximaDosis'])p(s['ProximaDosis'],{icon:'💉',color:'#e53e3e',txt:`${s['Tipo']||'Vacuna'}: ${s['Animal']||''}`});});const firstDay=new Date(calAno,calMes,1).getDay();const dIM=new Date(calAno,calMes+1,0).getDate();let html='<div style="display:grid;grid-template-columns:repeat(7,1fr);gap:2px;">';DS.forEach(d=>html+=`<div style="text-align:center;font-size:11px;font-weight:600;color:#9eaaba;padding:6px 0;">${d}</div>`);for(let i=0;i<firstDay;i++)html+=`<div></div>`;for(let day=1;day<=dIM;day++){const ds=`${calAno}-${String(calMes+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;const evs=evMap[ds]||[];const isHoy=hoy.getDate()===day&&hoy.getMonth()===calMes&&hoy.getFullYear()===calAno;html+=`<div style="min-height:70px;border:1px solid #e8edf5;border-radius:8px;padding:5px;background:${isHoy?'#f0f7ff':'#fff'};${isHoy?'border-color:#2E7DD6;':''}"><div style="font-size:13px;font-weight:${isHoy?700:400};color:${isHoy?'#2E7DD6':'#0D2B6B'};margin-bottom:3px;">${day}</div>${evs.slice(0,2).map(e=>`<div style="font-size:9px;background:${e.color}20;color:${e.color};border-radius:4px;padding:1px 4px;margin-bottom:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${e.icon} ${escH(e.txt)}</div>`).join('')}${evs.length>2?`<div style="font-size:9px;color:#9eaaba;">+${evs.length-2} más</div>`:''}</div>`;}html+='</div>';grid.innerHTML=html;}

// ══ ÁRBOL GENEALÓGICO ══
let _arbolTimer=null;
function arbolBuscarLive(val){clearTimeout(_arbolTimer);_arbolTimer=setTimeout(()=>{if(val.trim().length>=2)arbolBuscar(val.trim());else if(!val.trim()){const c=document.getElementById('arbol-resultado');if(c)c.innerHTML='<div class="arbol-empty"><div class="ei">🧬</div><p>Escribe el arete o nombre de un animal<br>para ver su árbol genealógico.</p></div>';}},300);}
function arbolBuscar(q){const val=(q||document.getElementById('arbol-input')?.value||'').trim().toLowerCase();if(!val)return;const animal=DB.animales.find(a=>(a['Arete']||'').toLowerCase().includes(val)||(a['Nombre']||'').toLowerCase().includes(val));const cont=document.getElementById('arbol-resultado');if(!animal){cont.innerHTML='<div class="arbol-empty"><div class="ei">🔍</div><p>No se encontró ningún animal con ese arete o nombre.</p></div>';return;}cont.dataset.tabArbol='padres';cont.dataset.arbolRaiz=animal['ID'];renderArbolAnimal(animal['ID']);}
function renderArbolAnimal(id){
  const animal=DB.animales.find(a=>String(a['ID'])===String(id));if(!animal)return;
  function dotC(e){if(!e||e==='Activo'||e==='Gestante')return'#22a96a';if(e==='Vendido')return'#9eaaba';if(e==='Muerto')return'#e53e3e';return'#F0A500';}
  function porA(arete){if(!arete)return null;return DB.animales.find(a=>(a['Arete']||'').toLowerCase()===arete.trim().toLowerCase())||null;}
  function par(a){if(!a)return{padre:null,padreArete:'',madre:null,madreArete:''};const pA=(a['Padre']||'').trim(),mA=(a['Madre']||'').trim();return{padreArete:pA,madreArete:mA,padre:porA(pA),madre:porA(mA)};}
  function cH(a,sel,ex){if(!a)return'';const sc=a['Sexo']==='Macho'?'macho':'hembra';return`<div class="arbol-animal ${sc}${sel?' selected':''}${ex?' '+ex:''}" onclick="renderArbolAnimal('${a['ID']}')" style="cursor:pointer;"><div class="arbol-dot" style="background:${dotC(a['Estado'])}"></div><div class="arbol-arete">${escH(a['Arete']||'')}</div><div class="arbol-nombre">${escH(a['Nombre']||'—')}</div><div class="arbol-raza">${escH(a['Raza']||'')}</div><span class="arbol-sexo ${a['Sexo']==='Macho'?'m':'h'}">${a['Sexo']==='Macho'?'♂ Macho':'♀ Hembra'}</span></div>`;}
  function cE(n,ex){if(!n)return'';return`<div class="arbol-animal externo${ex?' '+ex:''}" style="cursor:default;"><div class="arbol-dot" style="background:#F0A500"></div><div class="arbol-arete" style="color:#F0A500">${escH(n)}</div><div class="arbol-nombre" style="font-size:11px">Animal externo</div><div class="arbol-raza">No registrado</div><span class="arbol-externo-badge">🔗 Externo</span></div>`;}
  function slot(a,ar,ex){if(a)return cH(a,false,ex);if(ar)return cE(ar,ex);return'';}
  const p0=par(animal),pPad=par(p0.padre),pMad=par(p0.madre);
  const arB=(animal['Arete']||'').toLowerCase();
  const hijos=DB.animales.filter(a=>{const m=(a['Madre']||'').toLowerCase(),p=(a['Padre']||'').toLowerCase();return String(a['ID'])!==String(id)&&(m===arB||p===arB);});
  const machos=hijos.filter(h=>h['Sexo']==='Macho').length,hembras=hijos.filter(h=>h['Sexo']==='Hembra').length;
  const tieneA=p0.padre||p0.madre||p0.padreArete||p0.madreArete;
  const tienePP=pPad.padre||pPad.madre||pPad.padreArete||pPad.madreArete;
  const tienePM=pMad.padre||pMad.madre||pMad.padreArete||pMad.madreArete;
  const cont=document.getElementById('arbol-resultado');
  let tab=cont.dataset.tabArbol||'padres';
  if(tab==='abuelos'&&!tieneA)tab='padres';
  let html='<div class="arbol-wrap">';
  html+=`<div class="arbol-gen-tabs"><div class="arbol-gen-tab${tab==='padres'?' active':''}" onclick="arbolSetTab('padres')">👪 Padres</div>`;
  if(tieneA)html+=`<div class="arbol-gen-tab${tab==='abuelos'?' active':''}" onclick="arbolSetTab('abuelos')">🌿 Abuelos</div>`;
  html+='</div>';
  if(tab==='abuelos'){if(tienePP||tienePM){html+=`<div class="arbol-nivel-label">Abuelos</div><div class="arbol-nivel-gen">`;if(tienePP){const lP=p0.padre?`Padres de ${p0.padre['Nombre']||p0.padre['Arete']}`:`Vía padre (${p0.padreArete})`;html+=`<div class="arbol-gen-grupo"><div class="arbol-gen-grupo-label">♂ ${escH(lP)}</div><div class="arbol-nivel">${slot(pPad.padre,pPad.padreArete,'gen-abuelo')}${slot(pPad.madre,pPad.madreArete,'gen-abuelo')}</div></div>`;}if(tienePM){const lM=p0.madre?`Padres de ${p0.madre['Nombre']||p0.madre['Arete']}`:`Vía madre (${p0.madreArete})`;html+=`<div class="arbol-gen-grupo"><div class="arbol-gen-grupo-label">♀ ${escH(lM)}</div><div class="arbol-nivel">${slot(pMad.padre,pMad.padreArete,'gen-abuelo')}${slot(pMad.madre,pMad.madreArete,'gen-abuelo')}</div></div>`;}html+='</div><div class="arbol-vline-sm"></div>';}}
  if(p0.padre||p0.madre||p0.padreArete||p0.madreArete){html+=`<div class="arbol-nivel-label">Padres</div><div class="arbol-nivel">`;if(p0.padre)html+=cH(p0.padre,false,'');else if(p0.padreArete)html+=cE(p0.padreArete,'');if(p0.madre)html+=cH(p0.madre,false,'');else if(p0.madreArete)html+=cE(p0.madreArete,'');html+='</div><div class="arbol-vline"></div>';}
  html+=`<div class="arbol-nivel-label">${escH(animal['Nombre']||animal['Arete'])} — seleccionado</div><div class="arbol-nivel">${cH(animal,true,'')}</div>`;
  if(hijos.length){html+=`<div class="arbol-vline"></div><div class="arbol-nivel-label">Crías (${hijos.length})</div><div class="arbol-hijos-grid">`;hijos.forEach(h=>{html+=`<div class="arbol-hijo ${h['Sexo']==='Macho'?'macho':'hembra'}" onclick="renderArbolAnimal('${h['ID']}')"><div class="arbol-hijo-arete">${escH(h['Arete']||'')} ${h['Nombre']?'— '+escH(h['Nombre']):''}</div><div class="arbol-hijo-info">${escH(h['Raza']||'')} · ${h['Sexo']==='Macho'?'♂':'♀'} · <span style="color:${dotC(h['Estado'])}">${h['Estado']||'Activo'}</span></div></div>`;});html+='</div>';}else html+='<div style="text-align:center;padding:10px;font-size:12px;color:#9eaaba;">Sin crías registradas</div>';
  html+=`<div class="arbol-divider"><span>Resumen genético</span></div><div class="arbol-stats"><div class="arbol-stat"><div class="arbol-stat-val">${hijos.length}</div><div class="arbol-stat-lbl">Total crías</div></div><div class="arbol-stat"><div class="arbol-stat-val" style="color:#185FA5">${machos}</div><div class="arbol-stat-lbl">Machos</div></div><div class="arbol-stat"><div class="arbol-stat-val" style="color:#993556">${hembras}</div><div class="arbol-stat-lbl">Hembras</div></div></div>`;
  if(p0.padreArete||p0.madreArete){html+=`<div class="arbol-divider"><span>Información de padres</span></div><div class="arbol-padres-info">`;if(p0.padreArete){if(p0.padre)html+=`<div>🐂 <strong>Padre:</strong> ${escH(p0.padre['Nombre']||'')} (${escH(p0.padre['Arete'])}) — ${escH(p0.padre['Raza']||'')}</div>`;else html+=`<div>🧬 <strong>Padre (externo):</strong> ${escH(p0.padreArete)} <span style="background:rgba(240,200,74,.15);color:#F0A500;font-size:10px;padding:1px 7px;border-radius:20px;font-weight:700;margin-left:4px;">Otro rancho</span></div>`;}if(p0.madreArete){if(p0.madre)html+=`<div>🐄 <strong>Madre:</strong> ${escH(p0.madre['Nombre']||'')} (${escH(p0.madre['Arete'])}) — ${escH(p0.madre['Raza']||'')}</div>`;else html+=`<div>🐄 <strong>Madre (externa):</strong> ${escH(p0.madreArete)} <span style="background:rgba(240,200,74,.15);color:#F0A500;font-size:10px;padding:1px 7px;border-radius:20px;font-weight:700;margin-left:4px;">No registrada</span></div>`;}html+='</div>';}
  html+='</div>';cont.innerHTML=html;cont.dataset.tabArbol=tab;
}
function arbolSetTab(tab){const c=document.getElementById('arbol-resultado');if(!c)return;c.dataset.tabArbol=tab;const rid=c.dataset.arbolRaiz;if(rid)renderArbolAnimal(rid);}

// ══ BUSCAR ANIMAL ══
function buscarAnimal(q){const cont=document.getElementById('buscar-resultado');if(!cont)return;const term=(q||'').toLowerCase().trim();if(!term){cont.innerHTML='';return;}const list=DB.animales.filter(a=>(a['Arete']||'').toLowerCase().includes(term)||(a['Nombre']||'').toLowerCase().includes(term)||(a['Raza']||'').toLowerCase().includes(term));if(!list.length){cont.innerHTML='<div style="text-align:center;padding:40px;color:#9eaaba;font-size:14px;">🔍 No se encontraron animales</div>';return;}cont.innerHTML=`<div style="background:#fff;border:1px solid #e8edf5;border-radius:14px;overflow:hidden">`+list.map((a,i)=>`<div onclick="verAnimalDetalle('${a['ID']}')" style="display:flex;align-items:center;gap:12px;padding:14px 16px;cursor:pointer;border-bottom:${i===list.length-1?'none':'1px solid #f0f4fa'};">${a['Foto']?`<img src="${a['Foto']}" style="width:38px;height:38px;border-radius:10px;object-fit:cover;flex-shrink:0;">`:'<div style="width:38px;height:38px;border-radius:10px;background:#f8fafc;display:flex;align-items:center;justify-content:center;font-size:20px;flex-shrink:0;">🐄</div>'}<div style="flex:1;min-width:0"><div style="font-weight:700;color:#2E7DD6;font-size:14px;">${escH(a['Arete']||'')} ${a['Nombre']?'— '+escH(a['Nombre']):''}</div><div style="font-size:12px;color:#9eaaba;margin-top:2px">${escH(a['Raza']||'')} | ${a['Sexo']==='Hembra'?'♀ Hembra':'♂ Macho'}</div></div><span style="background:${a['Estado']==='Activo'?'#e8f5e9':'#fff3e0'};color:${a['Estado']==='Activo'?'#1b8e4e':'#e07b00'};border-radius:20px;font-size:11px;font-weight:600;padding:3px 9px;flex-shrink:0">${a['Estado']||''}</span><span style="color:#9eaaba;font-size:18px;margin-left:4px">›</span></div>`).join('')+`</div>`;}
function verAnimalDetalle(id){const a=DB.animales.find(x=>String(x['ID'])===String(id));if(!a)return;const edad=a['Nacimiento']?Math.floor((new Date()-new Date(a['Nacimiento']))/(365.25*24*3600*1000))+' años':'—';const rS=DB.salud.filter(s=>s['Animal']===a['Arete']);const rI=DB.insem.filter(r=>r['Hembra']===a['Arete']);const rP=DB.partos.filter(r=>r['Madre']===a['Arete']);const total=rS.length+rI.length+rP.length;const body=document.getElementById('m-buscar-detalle-body');body.innerHTML=`<div style="display:flex;align-items:center;gap:14px;margin-bottom:20px">${a['Foto']?`<img src="${a['Foto']}" style="width:56px;height:56px;border-radius:14px;object-fit:cover;flex-shrink:0;border:2px solid #e8edf5">`:'<div style="width:56px;height:56px;border-radius:14px;background:#f8fafc;display:flex;align-items:center;justify-content:center;font-size:30px;flex-shrink:0;">🐄</div>'}<div style="flex:1"><div style="font-size:16px;font-weight:700;color:#2E7DD6">${escH(a['Arete']||'')} ${a['Nombre']?'— '+escH(a['Nombre']):''}</div><div style="font-size:13px;color:#9eaaba;margin-top:3px">${escH(a['Raza']||'')} | ${a['Sexo']==='Hembra'?'♀ Hembra':'♂ Macho'}</div></div><div style="text-align:center;flex-shrink:0"><div style="font-size:26px;font-weight:800;color:#2E7DD6">${total}</div><div style="font-size:11px;color:#9eaaba">eventos</div></div></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:18px">${[['Edad',edad],['Peso',a['Peso']?a['Peso']+' kg':'—'],['Nacimiento',fmt(a['Nacimiento'])],['Madre',a['Madre']||'—']].map(([l,val])=>`<div style="background:#f8fafc;border-radius:10px;padding:12px;border:1px solid #e8edf5"><div style="font-size:10px;color:#9eaaba;text-transform:uppercase;letter-spacing:.5px;margin-bottom:4px">${l}</div><div style="font-size:14px;font-weight:600;color:#0D2B6B">${escH(val)}</div></div>`).join('')}</div>${rS.map(s=>`<div style="background:#f8fafc;border-radius:10px;border:1px solid #e8edf5;border-left:3px solid #2E7DD6;padding:10px 12px;margin-bottom:8px"><div style="font-size:11px;font-weight:700;color:#2E7DD6;text-transform:uppercase;margin-bottom:4px">💉 Salud — ${fmt(s['FechaAplicacion'])}</div><div style="font-size:13px;color:#0D2B6B">${escH(s['Descripcion']||s['Tipo']||'—')}</div></div>`).join('')}${rP.map(r=>`<div style="background:#f8fafc;border-radius:10px;border:1px solid #e8edf5;border-left:3px solid #22a96a;padding:10px 12px;margin-bottom:8px"><div style="font-size:11px;font-weight:700;color:#22a96a;text-transform:uppercase;margin-bottom:4px">🐣 Parto — ${fmt(r['Fecha'])}</div><div style="font-size:13px;color:#0D2B6B">Cría: ${escH(r['ArieteCria']||'—')} (${r['SexoCria']||'—'})</div></div>`).join('')}${rI.map(r=>`<div style="background:#f8fafc;border-radius:10px;border:1px solid #e8edf5;border-left:3px solid #F0A500;padding:10px 12px;margin-bottom:8px"><div style="font-size:11px;font-weight:700;color:#F0A500;text-transform:uppercase;margin-bottom:4px">🔬 Inseminación — ${fmt(r['Fecha'])}</div><div style="font-size:13px;color:#0D2B6B">Toro: ${escH(r['ToroSemen']||'—')} | ${escH(r['Resultado']||'Pendiente')}</div></div>`).join('')}${total===0?'<div style="text-align:center;padding:24px;color:#9eaaba;font-size:13px;">📭 Sin registros para este animal</div>':''}<div style="display:flex;gap:8px;margin-top:16px;justify-content:flex-end"><button onclick="closeM('m-buscar-detalle');editAnimal('${a['ID']}')" style="padding:9px 16px;border-radius:9px;border:1.5px solid #dde3ec;background:#fff;color:#4a5568;font-size:13px;font-weight:600;cursor:pointer;">✏️ Editar</button><button onclick="closeM('m-buscar-detalle')" style="padding:9px 18px;border-radius:9px;border:none;background:#2E7DD6;color:#fff;font-size:13px;font-weight:600;cursor:pointer;">Cerrar</button></div>`;document.getElementById('m-buscar-detalle-title').textContent=(a['Arete']||'')+(a['Nombre']?' — '+a['Nombre']:'');openM('m-buscar-detalle');}

// ══ MOB NAV ══
function mobMas(){const m=document.getElementById('mob-mas-menu');if(m){m.style.display='block';document.body.style.overflow='hidden';}}
function mobCerrarMas(){const m=document.getElementById('mob-mas-menu');if(m){m.style.display='none';document.body.style.overflow='';}}
function mobAgregar(){const m=document.getElementById('mob-add-menu');if(m){m.style.display='flex';document.body.style.overflow='hidden';}}
function mobCerrarAdd(){const m=document.getElementById('mob-add-menu');if(m){m.style.display='none';document.body.style.overflow='';}}
function mobNavegar(sec){mobCerrarMas();mobCerrarAdd();navegar(sec,null);}
function mobMasBuscar(q){q=(q||'').toLowerCase();document.querySelectorAll('.mob-mas-item,.mm-item').forEach(item=>{const txt=(item.textContent||'').toLowerCase();item.style.display=(!q||txt.includes(q))?'':'none';});}
function cerrarMobAnimales(){const mob=document.getElementById('mob-animales');if(mob)mob.style.display='none';document.body.style.overflow='';}

// ══ BANCO GENÉTICO ══
function bkTab(t){const g=document.getElementById('bk-grid'),d=document.getElementById('bk-dosis');const t1=document.getElementById('bk-t1'),t2=document.getElementById('bk-t2');if(t==='toros'){if(g)g.style.display='grid';if(d)d.classList.remove('on');if(t1)t1.classList.add('on');if(t2)t2.classList.remove('on');}else{if(g)g.style.display='none';if(d)d.classList.add('on');if(t2)t2.classList.add('on');if(t1)t1.classList.remove('on');}}
function bkFiltrar(){const q=(document.getElementById('bk-q')?.value||'').toLowerCase();const raza=document.getElementById('bk-raza')?.value||'';const disp=document.getElementById('bk-disp')?.value||'';document.querySelectorAll('#bk-grid .bk-card').forEach(c=>{c.style.display=(!q||(c.dataset.nombre||'').includes(q))&&(!raza||c.dataset.raza===raza)&&(!disp||c.dataset.disp===disp)?'':'none';});}
function bkVista(v){const g=document.getElementById('bk-grid'),vg=document.getElementById('bk-vg'),vl=document.getElementById('bk-vl');if(v==='grid'){if(g)g.style.gridTemplateColumns='repeat(auto-fill,minmax(310px,1fr))';if(vg)vg.classList.add('on');if(vl)vl.classList.remove('on');}else{if(g)g.style.gridTemplateColumns='1fr';if(vl)vl.classList.add('on');if(vg)vg.classList.remove('on');}}
function bkModal(open){const m=document.getElementById('bk-modal');if(m)m.style.display=open?'flex':'none';}

// ══ SOPORTE ══
function spChar(){const msgEl=document.getElementById('sp-msg');if(!msgEl)return;if(msgEl.value.length>500)msgEl.value=msgEl.value.slice(0,500);const n=document.getElementById('sp-char-n');if(n)n.textContent=Math.min(msgEl.value.length,500);}
function spEnviar(){const msg=document.getElementById('sp-msg')?.value?.trim()||'';if(!msg){const el=document.getElementById('sp-msg');if(el)el.style.borderColor='#e53e3e';return;}const el=document.getElementById('sp-msg');if(el){el.style.borderColor='';el.value='';}const n=document.getElementById('sp-char-n');if(n)n.textContent='0';toast('✅ Mensaje enviado. Te responderemos pronto.');}
function spFaqToggle(el){const isOpen=el.classList.contains('open');document.querySelectorAll('.sp-faq-item').forEach(i=>i.classList.remove('open'));if(!isOpen)el.classList.add('open');}
function spFaqBuscar(q){q=(q||'').toLowerCase();document.querySelectorAll('.sp-faq-item').forEach(item=>{const txt=item.querySelector('.sp-faq-q span')?.textContent?.toLowerCase()||'';item.style.display=(!q||txt.includes(q))?'':'none';});}

// ══ SUSCRIPCIÓN ══
var suModoAnual=false;
function suToggle(modo){suModoAnual=(modo==='anual');document.getElementById('su-t-mes')?.classList.toggle('on',!suModoAnual);document.getElementById('su-t-anu')?.classList.toggle('on',suModoAnual);}
function suSeleccionarPlan(plan){toast('Plan seleccionado: '+plan);}
function suMetodo(el){document.querySelectorAll('.su-metodo').forEach(m=>m.classList.remove('on'));el.classList.add('on');}
function suPagar(){toast('🔄 Procesando pago...');}

// ══ PERFIL ══
function pfToggle(btn){btn.classList.toggle('on');btn.classList.toggle('off');}
function pfCambiarLogo(input){if(!input.files||!input.files[0])return;const r=new FileReader();r.onload=e=>{const src=e.target.result;const img=document.getElementById('pf-logo-img');const prev=document.getElementById('pf-preview-img');if(img)img.src=src;if(prev)prev.src=src;};r.readAsDataURL(input.files[0]);}
function pfActualizarPreview(){const nombre=document.getElementById('pf-nombre-ganaderia'),ruc=document.getElementById('pf-ruc'),dir=document.getElementById('pf-direccion'),pname=document.getElementById('pf-preview-name'),pmeta=document.getElementById('pf-preview-meta');if(nombre&&pname)pname.textContent=nombre.value;if(ruc&&dir&&pmeta)pmeta.innerHTML='RUC: '+ruc.value+'<br>'+dir.value;}

// ══ DOCUMENTOS ══
function dcSelTipo(el,tipo){document.querySelectorAll('.dc-tipo').forEach(t=>{t.style.borderColor='';t.style.background='';});el.style.borderColor='#2E7DD6';el.style.background='#f0f7ff';toast('Generando: '+tipo+'...');}
function dcBuscar(q){q=(q||'').toLowerCase();document.querySelectorAll('#dc-tbody tr').forEach(tr=>{tr.style.display=(!q||tr.textContent.toLowerCase().includes(q))?'':'none';});}
function dcFiltrar(){const tipo=document.getElementById('dc-filtro-tipo')?.value?.toLowerCase()||'';document.querySelectorAll('#dc-tbody tr').forEach(tr=>{tr.style.display=(!tipo||tr.textContent.toLowerCase().includes(tipo))?'':'none';});}
function dcLimpiar(){const el=document.getElementById('dc-filtro-tipo');if(el)el.value='';document.querySelectorAll('#dc-tbody tr').forEach(tr=>{tr.style.display='';});}

// ══ EXPORTAR ══
function exDescargar(tipo){toast('⬇️ Preparando descarga...');if(window.XLSX&&DB.animales.length){try{const wb=XLSX.utils.book_new();if(tipo==='animales'||tipo==='completo'){const ws=XLSX.utils.json_to_sheet(DB.animales.map(a=>({'Arete':a['Arete'],'Nombre':a['Nombre'],'Raza':a['Raza'],'Sexo':a['Sexo'],'Nacimiento':a['Nacimiento'],'Peso':a['Peso'],'Estado':a['Estado'],'Madre':a['Madre'],'Padre':a['Padre']})));XLSX.utils.book_append_sheet(wb,ws,'Animales');}if(tipo==='salud'||tipo==='completo'){const ws=XLSX.utils.json_to_sheet(DB.salud.map(s=>({'Animal':s['Animal'],'Tipo':s['Tipo'],'Descripción':s['Descripcion'],'Fecha Aplicación':s['FechaAplicacion'],'Próxima Dosis':s['ProximaDosis'],'Veterinario':s['Veterinario']})));XLSX.utils.book_append_sheet(wb,ws,'Salud');}if(tipo==='gastos'||tipo==='completo'){const ws=XLSX.utils.json_to_sheet(DB.gastos.map(g=>({'Tipo':g['Tipo'],'Descripción':g['Descripcion'],'Monto':g['Monto'],'Es Ingreso':g['EsIngreso'],'Fecha':g['Fecha'],'Animal':g['Animal']})));XLSX.utils.book_append_sheet(wb,ws,'Gastos');}if(wb.SheetNames.length){XLSX.writeFile(wb,(tipo||'datos')+'.xlsx');toast('✅ Archivo descargado');}}catch(e){toast('❌ Error al generar: '+e.message);}}}
function imDescargarPlantilla(){toast('⬇️ Descargando plantilla...');}
function imSeleccionarArchivo(input){if(!input.files||!input.files[0])return;const file=input.files[0];const fn=document.getElementById('im-file-name'),fs=document.getElementById('im-file-size'),fp=document.getElementById('im-file-preview'),dz=document.getElementById('im-drop-zone'),btn=document.getElementById('im-btn-validar');if(fn)fn.textContent=file.name;if(fs)fs.textContent=(file.size/1024).toFixed(1)+' KB';if(fp)fp.classList.add('show');if(dz)dz.style.display='none';if(btn){btn.disabled=false;btn.classList.add('ready');}}
function imQuitarArchivo(){const fi=document.getElementById('im-file-input');if(fi)fi.value='';const fp=document.getElementById('im-file-preview');if(fp)fp.classList.remove('show');const dz=document.getElementById('im-drop-zone');if(dz)dz.style.display='flex';const btn=document.getElementById('im-btn-validar');if(btn){btn.disabled=true;btn.classList.remove('ready');}}
function imDragOver(e){e.preventDefault();document.getElementById('im-drop-zone')?.classList.add('dragover');}
function imDragLeave(){document.getElementById('im-drop-zone')?.classList.remove('dragover');}
function imDrop(e){e.preventDefault();document.getElementById('im-drop-zone')?.classList.remove('dragover');const files=e.dataTransfer?.files;if(files&&files[0]){const input=document.getElementById('im-file-input');const dt=new DataTransfer();dt.items.add(files[0]);if(input){input.files=dt.files;imSeleccionarArchivo(input);}}}
function imValidar(){toast('🔍 Validando archivo...');}

