// ══ ONLINE/OFFLINE ══
window.addEventListener('online',()=>{isOnline=true;const ob=document.getElementById('offline-bar');if(ob)ob.style.display='none';setSyncStatus('syncing','🔄 Reconectando...');setTimeout(recargarTodo,1500);});
window.addEventListener('offline',()=>{isOnline=false;setSyncStatus('err','📵 Sin internet');const ob=document.getElementById('offline-bar');if(ob){ob.style.display='block';ob.textContent='📵 Sin conexión — los cambios se sincronizarán al reconectar';}});

// ══ INIT ══
document.addEventListener('DOMContentLoaded',()=>{
  cambiarTab('login');
  // Limpiar errores al escribir
  [['email-login'],['pass-login'],['reg-nombre'],['reg-rancho'],['reg-email'],['reg-pass']].forEach(([id])=>{const el=document.getElementById(id);if(el)el.addEventListener('input',()=>clearErr(id));});
  document.getElementById('pass-login')?.addEventListener('keydown',e=>{if(e.key==='Enter')iniciarSesion();});
  document.getElementById('reg-pass')?.addEventListener('keydown',e=>{if(e.key==='Enter')crearCuenta();});
  // Busqueda animales
  const anSearch=document.getElementById('an-buscar');if(anSearch)anSearch.addEventListener('input',()=>filtrar(anSearch.value.toLowerCase()));
  // Botones nuevo animal
  document.querySelectorAll('.an-btn-nuevo').forEach(btn=>{if(!btn.onclick&&!btn.getAttribute('onclick'))btn.addEventListener('click',abrirModalAnimal);});
  // Restaurar sesion
  try{const s=JSON.parse(localStorage.getItem('vq_sesion')||'null');if(s&&s.user_id){mostrarDashboard(s);}else{document.getElementById('pantalla-login').style.display='flex';}}catch(e){document.getElementById('pantalla-login').style.display='flex';}
  // Service Worker
  if('serviceWorker' in navigator){navigator.serviceWorker.register('sw.js').catch(err=>console.log('SW:',err));}
});
